const CATEGORY_BY_KEYWORD = {
  "AI": "AI",
  "Web Development": "Web Development",
  "SaaS": "SaaS",
  "Startup": "Startup",
  "Next.js": "Web Development",
  "React": "Web Development",
  "AI Agents": "AI Agents",
  "Automation": "Automation",
  "LinkedIn": null
};

const inputItems = $input.all();
const keywordItems = $('HN: Keywords').all();
const results = [];

for (let idx = 0; idx < inputItems.length; idx++) {
  const keyword = keywordItems[idx].json.keyword;
  const hits = (inputItems[idx].json && inputItems[idx].json.hits) || [];

  for (const hit of hits) {
    if (!hit.title) continue;
    const url = hit.url || `https://news.ycombinator.com/item?id=${hit.objectID}`;
    results.push({
      topic: hit.title.slice(0, 300),
      summary: `${hit.points || 0} points, ${hit.num_comments || 0} comments on Hacker News.`,
      sourceName: "Hacker News",
      sourceUrl: url,
      rawScore: hit.points || 0,
      rawScoreType: "log",
      publishedAt: hit.created_at || null,
      hintCategory: CATEGORY_BY_KEYWORD[keyword] || null
    });
  }
}

return results.map((r) => ({ json: r }));

const CATEGORY_BY_TAG = {
  ai: "AI",
  webdev: "Web Development",
  saas: "SaaS",
  startup: "Startup",
  nextjs: "Web Development",
  react: "Web Development",
  llm: "AI Agents",
  automation: "Automation"
};

// dev.to returns a bare JSON array, so n8n auto-splits it into one item per
// article rather than one item per request -- pairedItem is how we recover
// which tag produced each article (see the workflow doc's "pairedItem vs
// index alignment" note for why this differs from the HN/GitHub branches).
const tagItems = $('DevTo: Tags').all();
const results = [];

for (const item of $input.all()) {
  const article = item.json;
  if (!article || !article.title) continue;

  const tagIndex = item.pairedItem ? item.pairedItem.item : undefined;
  const tag = tagIndex !== undefined ? tagItems[tagIndex].json.tag : undefined;

  results.push({
    topic: article.title.slice(0, 300),
    summary: (article.description || "").slice(0, 500),
    sourceName: "dev.to",
    sourceUrl: article.url,
    rawScore: (article.public_reactions_count || 0) + (article.comments_count || 0),
    rawScoreType: "log",
    publishedAt: article.published_timestamp || null,
    hintCategory: (tag && CATEGORY_BY_TAG[tag]) || null
  });
}

return results.map((r) => ({ json: r }));

const topics = ["artificial-intelligence", "web", "saas", "ai-agents", "automation", "startup"];
const since = new Date(Date.now() - 60 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
return topics.map((topic) => ({ json: { topic, since } }));

const CATEGORY_BY_TOPIC = {
  "artificial-intelligence": "AI",
  "web": "Web Development",
  "saas": "SaaS",
  "ai-agents": "AI Agents",
  "automation": "Automation",
  "startup": "Startup"
};

// GitHub's Search API returns a JSON OBJECT ({total_count, items: [...]}),
// not a bare array, so n8n keeps one item per request here -- index
// alignment with the originating "Topics" item is safe (see doc note).
const inputItems = $input.all();
const topicItems = $('GitHub: Topics').all();
const results = [];

for (let idx = 0; idx < inputItems.length; idx++) {
  const topic = topicItems[idx].json.topic;
  const repos = (inputItems[idx].json && inputItems[idx].json.items) || [];

  for (const repo of repos) {
    if (!repo.full_name) continue;
    results.push({
      topic: `${repo.full_name}${repo.description ? ": " + repo.description : ""}`.slice(0, 300),
      summary: (repo.description || "No description provided.").slice(0, 500),
      sourceName: "GitHub Trending",
      sourceUrl: repo.html_url,
      rawScore: repo.stargazers_count || 0,
      rawScoreType: "log",
      publishedAt: repo.pushed_at || repo.created_at || null,
      hintCategory: CATEGORY_BY_TOPIC[topic] || null
    });
  }
}

return results.map((r) => ({ json: r }));

const response = $input.first().json;
const edges = (response.data && response.data.posts && response.data.posts.edges) || [];
const results = [];

for (const edge of edges) {
  const node = edge.node;
  if (!node || !node.name) continue;

  const topicNames = ((node.topics && node.topics.edges) || []).map((e) => (e.node.name || "").toLowerCase());
  let hintCategory = null;
  if (topicNames.some((t) => t.includes("artificial") || t === "ai")) hintCategory = "AI";
  else if (topicNames.some((t) => t.includes("saas"))) hintCategory = "SaaS";
  else if (topicNames.some((t) => t.includes("developer") || t.includes("web"))) hintCategory = "Web Development";
  else if (topicNames.some((t) => t.includes("productivity") || t.includes("automation"))) hintCategory = "Automation";
  else if (topicNames.some((t) => t.includes("startup"))) hintCategory = "Startup";

  results.push({
    topic: `${node.name}${node.tagline ? " - " + node.tagline : ""}`.slice(0, 300),
    summary: (node.tagline || "").slice(0, 500),
    sourceName: "Product Hunt",
    sourceUrl: node.url,
    rawScore: node.votesCount || 0,
    rawScoreType: "log",
    publishedAt: node.createdAt || null,
    hintCategory
  });
}

return results.map((r) => ({ json: r }));

const CATEGORY_BY_KEYWORD = {
  "AI": "AI",
  "Web Development": "Web Development",
  "SaaS": "SaaS",
  "Startup": "Startup",
  "Next.js": "Web Development",
  "React": "Web Development",
  "AI Agents": "AI Agents",
  "Automation": "Automation",
  "LinkedIn": null
};

// Google News RSS returns one <item> per article; RSS Feed Read parses
// that into one n8n item per article already, so we use pairedItem
// (not index alignment) to recover which keyword produced each one.
const keywordItems = $('GNews: Keywords').all();
const results = [];

for (const item of $input.all()) {
  const entry = item.json;
  if (!entry || !entry.title) continue;

  const kwIndex = item.pairedItem ? item.pairedItem.item : undefined;
  const keyword = kwIndex !== undefined ? keywordItems[kwIndex].json.keyword : undefined;

  results.push({
    topic: entry.title.slice(0, 300),
    summary: (entry.contentSnippet || entry.content || "").replace(/<[^>]*>/g, "").slice(0, 500),
    sourceName: "Google News",
    sourceUrl: entry.link,
    rawScore: null,
    rawScoreType: "unranked",
    publishedAt: entry.isoDate || entry.pubDate || null,
    hintCategory: (keyword && CATEGORY_BY_KEYWORD[keyword]) || null
  });
}

return results.map((r) => ({ json: r }));

const subreddits = [
  { subreddit: "artificial", hintCategory: "AI" },
  { subreddit: "ChatGPT", hintCategory: "AI Agents" },
  { subreddit: "webdev", hintCategory: "Web Development" },
  { subreddit: "programming", hintCategory: "Web Development" },
  { subreddit: "Entrepreneur", hintCategory: "Startup" }
];
return subreddits.map((s) => ({ json: s }));

// Reddit's unauthenticated JSON endpoint (www.reddit.com/.../top.json)
// reliably returns 403 from most hosting IPs; the legacy `.rss` Atom
// endpoint does not carry a vote/score field, and there's no guarantee an
// XML-parsing library is available inside n8n's Code node sandbox, so this
// does a small, deliberately narrow regex extraction instead of a full XML
// parse. If Reddit changes its Atom output structure, this is the node to
// revisit (see the workflow doc's Reddit section).
const CATEGORY_FALLBACK = null;
const inputItems = $input.all();
const subItems = $('Reddit: Subreddits').all();
const results = [];

for (let idx = 0; idx < inputItems.length; idx++) {
  const subreddit = subItems[idx].json.subreddit;
  const hintCategory = subItems[idx].json.hintCategory || CATEGORY_FALLBACK;
  const xml = (inputItems[idx].json && inputItems[idx].json.data) || "";
  const entryChunks = xml.split("<entry>").slice(1);

  for (const chunk of entryChunks) {
    const titleMatch = chunk.match(/<title>([\s\S]*?)<\/title>/);
    const linkMatch = chunk.match(/<link[^>]*href="([^"]+)"/);
    const updatedMatch = chunk.match(/<updated>([^<]*)<\/updated>/);
    const title = titleMatch ? titleMatch[1].trim() : "";
    if (!title) continue;

    results.push({
      topic: title.slice(0, 300),
      summary: `Trending on r/${subreddit}.`,
      sourceName: `Reddit (r/${subreddit})`,
      sourceUrl: linkMatch ? linkMatch[1] : `https://www.reddit.com/r/${subreddit}/`,
      rawScore: null,
      rawScoreType: "unranked",
      publishedAt: updatedMatch ? updatedMatch[1] : null,
      hintCategory
    });
  }
}

return results.map((r) => ({ json: r }));

