const seen = new Map();

for (const item of $input.all()) {
  const t = item.json;
  if (!t.sourceUrl || !t.topic) continue;
  const key = t.sourceUrl.toLowerCase().trim();
  const currentScore = typeof t.rawScore === "number" ? t.rawScore : -1;
  const existing = seen.get(key);
  const existingScore = existing && typeof existing.rawScore === "number" ? existing.rawScore : -1;

  if (!existing || currentScore > existingScore) {
    seen.set(key, t);
  }
}

return Array.from(seen.values()).map((t) => ({ json: t }));

function computeScore(t) {
  if (t.rawScoreType === "editorial") return 70;
  if (t.rawScoreType === "unranked") return 50;
  const raw = typeof t.rawScore === "number" && t.rawScore > 0 ? t.rawScore : 0;
  return Math.max(0, Math.min(100, Math.round(Math.log10(raw + 1) * 30)));
}

return $input.all().map((item) => {
  const t = item.json;
  return { json: { ...t, score: computeScore(t) } };
});

const CATEGORIES = ["AI", "Web Development", "SaaS", "AI Agents", "Automation", "Startup"];

const KEYWORD_RULES = [
  { category: "AI Agents", pattern: /\b(ai agent|autonomous agent|agentic|multi-agent)\b/i },
  { category: "AI", pattern: /\b(artificial intelligence|machine learning|\bllm\b|\bgpt\b|gemini|claude|openai|anthropic|deep learning|neural network)\b/i },
  { category: "Automation", pattern: /\b(automation|automate|workflow|no-code|low-code|n8n|zapier)\b/i },
  { category: "SaaS", pattern: /\b(saas|subscription|b2b software|software as a service)\b/i },
  { category: "Startup", pattern: /\b(startup|funding|venture capital|\bvc\b|seed round|series [abc]|founder)\b/i },
  { category: "Web Development", pattern: /\b(react|next\.?js|javascript|typescript|frontend|front-end|web development|css|html|node\.js)\b/i }
];

return $input.all().map((item) => {
  const t = item.json;
  let category = t.hintCategory && CATEGORIES.includes(t.hintCategory) ? t.hintCategory : null;

  if (!category) {
    const text = `${t.topic} ${t.summary || ""}`;
    for (const rule of KEYWORD_RULES) {
      if (rule.pattern.test(text)) {
        category = rule.category;
        break;
      }
    }
  }

  return { json: { ...t, category: category || "Other" } };
});

const MAX_AGE_DAYS = 14;
const now = Date.now();

const items = $input.all()
  .map((item) => item.json)
  .filter((t) => {
    if (!t.publishedAt) return true;
    const published = new Date(t.publishedAt).getTime();
    if (Number.isNaN(published)) return true;
    const ageDays = (now - published) / (1000 * 60 * 60 * 24);
    return ageDays <= MAX_AGE_DAYS;
  })
  .sort((a, b) => b.score - a.score)
  .slice(0, 30)
  .map((t) => ({
    topic: t.topic,
    summary: t.summary,
    sourceName: t.sourceName,
    sourceUrl: t.sourceUrl,
    category: t.category,
    score: t.score,
    publishedAt: t.publishedAt || undefined
  }));

return [{ json: { trends: items, count: items.length } }];
